-- DRAFT ONLY: additive schema inventory from Service Flow runtime DDL.
-- Not a production migration. Namespaces are flattened/prefixed because D1 has no PostgreSQL schemas.
-- PostgreSQL behavior, sequence semantics, UUID generation, and app access adapters are not migrated here.
PRAGMA foreign_keys = ON;

-- Runtime tables absent from the 67 Drizzle declarations.
CREATE TABLE "current_fault_major_selections" ("ticket_id" TEXT PRIMARY KEY, "selected_by_id" INTEGER REFERENCES "users"("id"), "selected_by_name" TEXT, "selected_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "line_po_events" ("account_no" TEXT PRIMARY KEY, "last_raise_at" TEXT, "last_stop_at" TEXT, "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "last_raise_by" TEXT, "last_stop_by" TEXT);
CREATE TABLE "op_intents" ("account" TEXT NOT NULL, "op_type" TEXT NOT NULL, "username" TEXT, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("account", "op_type"));
CREATE TABLE "om_manual_mobiles" ("serial_number" TEXT PRIMARY KEY, "mobile" TEXT, "updated_by" TEXT, "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "line_subscriber_info" ("phone_number" TEXT PRIMARY KEY, "sub_name" TEXT, "sub_add" TEXT, "work_ord_date" TEXT, "work_ord_no" TEXT, "fetched_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "central" TEXT, "cabin_number" TEXT, "box_number" TEXT, "dp_terminal" TEXT, "port_no" TEXT, "idu_no" TEXT, "odu_no" TEXT, "primary_block" TEXT, "sec_block" TEXT, "cabinet_in" TEXT, "cabinet_out" TEXT, "fiber_block" TEXT, "fiber_out" TEXT, "line_type" TEXT);
CREATE TABLE "port_change_requests" ("request_id" TEXT PRIMARY KEY, "phone_number" TEXT, "old_msan" TEXT, "new_msan" TEXT, "new_frame" TEXT, "port_type" TEXT, "status" TEXT, "reservation_code" TEXT, "request_date" TEXT, "completed" INTEGER NOT NULL DEFAULT 0, "recorded_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "requested_by" TEXT);
CREATE INDEX "port_change_requests_phone_idx" ON "port_change_requests" ("phone_number");

-- Cable Fault Manager tables: app-generated text IDs must replace gen_random_uuid().
CREATE TABLE "cfm_users" ("id" TEXT PRIMARY KEY, "username" TEXT NOT NULL UNIQUE, "password" TEXT NOT NULL, "name" TEXT NOT NULL, "role" TEXT NOT NULL, "avatar" TEXT, "is_initial_password" INTEGER DEFAULT 1, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "suspended" INTEGER DEFAULT 0);
CREATE TABLE "centrals" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "code" TEXT NOT NULL UNIQUE, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "cables" ("id" TEXT PRIMARY KEY, "central_id" TEXT NOT NULL REFERENCES "centrals"("id") ON DELETE CASCADE, "number" TEXT NOT NULL, "cable_number" TEXT, "cabinet_number" TEXT, "type" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("central_id", "number"));
CREATE TABLE "fault_types" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "work_types" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "associated_materials" TEXT, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "task_types" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "contractors" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "excavation_workers" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "national_id" TEXT NOT NULL UNIQUE, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "tickets" ("id" TEXT PRIMARY KEY, "ticket_number" TEXT NOT NULL UNIQUE, "central_department" TEXT NOT NULL, "central_id" TEXT NOT NULL REFERENCES "centrals"("id"), "cable_id" TEXT NOT NULL REFERENCES "cables"("id"), "cabinet" TEXT NOT NULL, "box" TEXT NOT NULL, "fault_type_id" TEXT NOT NULL REFERENCES "fault_types"("id"), "notes" TEXT, "latitude" REAL, "longitude" REAL, "status" TEXT NOT NULL DEFAULT 'open', "final_repair_id" TEXT, "final_repair_description" TEXT, "final_repair_repaired_at" TEXT, "final_repair_repaired_by" TEXT, "closed_at" TEXT, "closed_by" TEXT, "created_by" TEXT NOT NULL REFERENCES "cfm_users"("id"), "opened_by_label" TEXT, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ticket_number_idx" ON "tickets" ("ticket_number");
CREATE INDEX "status_idx" ON "tickets" ("status");
CREATE TABLE "measurement_entries" ("id" TEXT PRIMARY KEY, "ticket_id" TEXT NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "reading" TEXT NOT NULL, "distance" REAL, "direction" TEXT, "notes" TEXT, "performed_by" TEXT, "created_by" TEXT NOT NULL REFERENCES "cfm_users"("id"), "recorded_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "work_entries" ("id" TEXT PRIMARY KEY, "ticket_id" TEXT NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "measurement_id" TEXT REFERENCES "measurement_entries"("id") ON DELETE CASCADE, "items" TEXT NOT NULL, "notes" TEXT, "performed_by" TEXT NOT NULL, "works_by" TEXT, "contractor_id" TEXT REFERENCES "contractors"("id"), "created_by" TEXT NOT NULL REFERENCES "cfm_users"("id"), "recorded_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "used_task_entries" ("id" TEXT PRIMARY KEY, "ticket_id" TEXT NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "measurement_id" TEXT REFERENCES "measurement_entries"("id") ON DELETE CASCADE, "items" TEXT NOT NULL, "notes" TEXT, "performed_by" TEXT NOT NULL, "created_by" TEXT NOT NULL REFERENCES "cfm_users"("id"), "recorded_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "inventory_transactions" ("id" TEXT PRIMARY KEY, "type" TEXT NOT NULL, "task_type_id" TEXT NOT NULL REFERENCES "task_types"("id"), "quantity" INTEGER NOT NULL, "date" TEXT NOT NULL, "ticket_id" TEXT REFERENCES "tickets"("id") ON DELETE SET NULL, "notes" TEXT, "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

-- Maintenance schema is flattened with a prefix to avoid collisions with public.users and other core tables.
CREATE TABLE "maintenance_exchanges" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "maintenance_cabinets" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "exchange_id" INTEGER NOT NULL REFERENCES "maintenance_exchanges"("id") ON DELETE CASCADE, "number" TEXT NOT NULL, UNIQUE ("exchange_id", "number"));
CREATE TABLE "maintenance_users" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "username" TEXT NOT NULL UNIQUE, "password" TEXT NOT NULL, "role" TEXT NOT NULL CHECK ("role" IN ('admin','inspector','technician')), "full_name" TEXT DEFAULT '', "email" TEXT DEFAULT '', "is_active" INTEGER DEFAULT 1, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "worker_code" TEXT);
CREATE TABLE "maintenance_boxes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "cabinet_id" INTEGER NOT NULL REFERENCES "maintenance_cabinets"("id") ON DELETE CASCADE, "number" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending_inspection' CHECK ("status" IN ('pending_inspection','inspected','needs_maintenance','in_progress','pending_approval','completed')), "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP, "latitude" REAL, "longitude" REAL, UNIQUE ("cabinet_id", "number"));
CREATE TABLE "maintenance_inspections" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "box_id" INTEGER NOT NULL REFERENCES "maintenance_boxes"("id"), "inspector_id" INTEGER NOT NULL REFERENCES "maintenance_users"("id"), "date" TEXT DEFAULT CURRENT_DATE, "general_notes" TEXT DEFAULT '', "is_archived" INTEGER DEFAULT 0, "latitude" REAL, "longitude" REAL, "opened_by_name" TEXT, "origin" TEXT, "origin_ref" TEXT, "auto_created" INTEGER DEFAULT 0);
CREATE TABLE "maintenance_inspection_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "inspection_id" INTEGER NOT NULL REFERENCES "maintenance_inspections"("id") ON DELETE CASCADE, "item_key" TEXT NOT NULL, "item_type" TEXT NOT NULL CHECK ("item_type" IN ('good_bad','yes_no')), "value" TEXT NOT NULL, "notes" TEXT DEFAULT '', "extra_type" TEXT, "extra_distance" REAL, UNIQUE ("inspection_id", "item_key"));
CREATE TABLE "maintenance_tasks" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "inspection_id" INTEGER NOT NULL REFERENCES "maintenance_inspections"("id"), "technician_id" INTEGER REFERENCES "maintenance_users"("id"), "notes" TEXT DEFAULT '', "started_at" TEXT, "completed_at" TEXT, "status" TEXT NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','in_progress','pending_approval','completed')), "rejection_reason" TEXT, "prelim_confirmed_at" TEXT, "prelim_confirmed_by" INTEGER);
CREATE TABLE "maintenance_item_status" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "task_id" INTEGER NOT NULL REFERENCES "maintenance_tasks"("id") ON DELETE CASCADE, "item_key" TEXT NOT NULL, "is_done" INTEGER DEFAULT 0, "done_at" TEXT, "done_by" INTEGER REFERENCES "maintenance_users"("id"), UNIQUE ("task_id", "item_key"));
CREATE TABLE "maintenance_photos" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "box_id" INTEGER NOT NULL REFERENCES "maintenance_boxes"("id"), "inspection_id" INTEGER REFERENCES "maintenance_inspections"("id"), "photo_type" TEXT NOT NULL CHECK ("photo_type" IN ('before','after')), "filename" TEXT NOT NULL, "uploaded_by" INTEGER REFERENCES "maintenance_users"("id"), "uploaded_at" TEXT DEFAULT CURRENT_TIMESTAMP, "taken_at" TEXT, "latitude" REAL, "longitude" REAL, "data" BLOB, "media_type" TEXT DEFAULT 'photo', "storage_key" TEXT);
CREATE TABLE "maintenance_box_line_numbers" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "inspection_id" INTEGER NOT NULL REFERENCES "maintenance_inspections"("id") ON DELETE CASCADE, "phone" TEXT NOT NULL, "notes" TEXT DEFAULT '', "source" TEXT NOT NULL DEFAULT 'service_flow', "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "maintenance_box_line_numbers_insp_idx" ON "maintenance_box_line_numbers" ("inspection_id");
CREATE TABLE "maintenance_cabinet_codes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "exchange_name" TEXT NOT NULL, "cabinet_number" TEXT NOT NULL, "exchange_code" TEXT, "decent_life" TEXT, "area_technician" TEXT, "worker_code" TEXT, "cabinet_code" TEXT, UNIQUE ("exchange_name", "cabinet_number"));
CREATE INDEX "maintenance_boxes_cabinet_idx" ON "maintenance_boxes" ("cabinet_id");
CREATE INDEX "maintenance_inspections_box_idx" ON "maintenance_inspections" ("box_id");
CREATE INDEX "maintenance_tasks_inspection_idx" ON "maintenance_tasks" ("inspection_id");
CREATE INDEX "maintenance_photos_box_idx" ON "maintenance_photos" ("box_id");
